WITH unpacked AS (SELECT id, host, log_ts, latency_ms, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, context['version'] AS version FROM app_logs WHERE host IN ('h4', 'h1')) SELECT id, host, log_ts, latency_ms, retry_count, version, MAX(latency_ms) OVER (PARTITION BY DATE_TRUNC('YEAR', log_ts), host ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS latency_ms_max_30m, LAG(retry_count, 1) OVER (PARTITION BY host ORDER BY retry_count, id) AS prev_retry_count, LAG(retry_count, 1, 0) OVER (PARTITION BY host ORDER BY latency_ms, id) AS prev_retry_count_2, CUME_DIST() OVER w_grp AS latency_ms_cume_dist, SUM(latency_ms) OVER (PARTITION BY host ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS latency_ms_sum_2h FROM unpacked WINDOW w_grp AS (PARTITION BY host ORDER BY latency_ms DESC)
